using System;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
static class WindReportFile {
 static string F(double n){return WindTin.Finite(n)?n.ToString("0.###",CultureInfo.InvariantCulture):"Unresolved";}
 public static EngineeringReport Create(double lat,double lon,string category,double z,double kd,WindTerrain terrain,bool reviewed,WindBuildingInput building,string project,string location,string office="",string mapPng=""){
  var wind=WindTin.At(lat,lon,category);var report=ProfessionalReport.Create("Wind load calculation",project,location,office);report.Status=reviewed?"Terrain review recorded":"Preliminary · terrain review pending";report.Subtitle="NSCP 2015 · Site wind speed, directional exposure, topography and building surface pressures";
  var directions=terrain==null?new List<WindDirection>():WindAssessment.Calculate(terrain,z,wind.V,kd,building==null?(double?)null:building.Height);
  report.Highlights.Add(new KeyValuePair<string,string>("Basic wind speed",F(wind.V)+" km/h"));report.Highlights.Add(new KeyValuePair<string,string>("Reference height",F(z)+" m"));report.Highlights.Add(new KeyValuePair<string,string>("Directionality factor",F(kd)));
  var input=report.Section("Design basis and site inputs");input.Table(new[]{"Parameter","Value / basis"},new[]{new[]{"Site coordinates",lat.ToString("0.######",CultureInfo.InvariantCulture)+"° N, "+lon.ToString("0.######",CultureInfo.InvariantCulture)+"° E"},new[]{"NSCP occupancy category",category},new[]{"Basic wind speed",F(wind.V)+" km/h = "+F(wind.V/3.6)+" m/s"},new[]{"Velocity-pressure reference height",F(z)+" m above local ground"},new[]{"Wind directionality factor Kd",F(kd)},new[]{"Terrain radius",terrain==null?"Not loaded":F(terrain.Radius)+" m from project site"},new[]{"Terrain acquisition",terrain==null?"Not loaded":terrain.Acquired.ToUniversalTime().ToString("dd MMM yyyy HH:mm 'UTC'",CultureInfo.InvariantCulture)}});
  input.Note("Wind speed is interpolated from the supplied NSCP raster contours using Delaunay TIN. Raster registration and contour digitization limit accuracy. Land cover screens potential surface roughness; obstruction height, directional fetch, topographic feature isolation and site conditions require review.");
  var site=report.Section("Site map and directional roughness");if(mapPng!="")site.Figure(mapPng,"Project-site map viewport with surface-roughness overlay and eight wind-from directions. Street/satellite attribution is included in the image.");else if(terrain!=null)site.Figure(RoughnessPlan(terrain,z),"Georeferenced roughness screening around the saved project site. Sector boundaries are 45° wind-from sectors; colors identify potential B (green), C (gold), D (blue), unknown (gray). This diagram is not street/satellite imagery.",true);else site.Note("Load site terrain to include the map and roughness screening.");
  if(terrain!=null){site.Table(new[]{"Wind from","Upwind sectors investigated","Mapped roughness mix","Suggested exposure"},directions.Select((d,i)=>new[]{d.Name,((terrain.Offset+i*45+315)%360).ToString("0",CultureInfo.InvariantCulture)+"° to "+((terrain.Offset+i*45+45)%360).ToString("0",CultureInfo.InvariantCulture)+"° (±45°)",d.ExposureAudit==null?"":d.ExposureAudit.Mix,d.Exposure}));}
  var topo=report.Section("Topographic factor and velocity pressure");topo.NewPage=false;topo.Equation("Kzt = (1 + K1 K2 K3)²\nKz = 2.01 [max(z, 4.57) / zg]^(2/α)\nqz = 0.613 Kz Kzt Kd (V / 3.6)² / 1000  [kPa]");
  topo.Table(new[]{"From","Feature","H m","Lh m","K1","K2","K3","Kzt","Kz","qz kPa"},directions.Select(d=>new[]{d.Name,d.Shape,F(d.H),F(d.Lh),F(d.K1),F(d.K2),F(d.K3),F(d.Kzt),F(d.Kz),F(d.Qz)}));
  topo.Note("The table uses the site reference height z. Building pressure calculations below recalculate exposure/topography at the actual building height and Kzt at each windward-wall height. Unresolved values are not replaced with default factors.");
  if(directions.Count>0){var exposure=report.Section("Exposure category determination by direction");exposure.NewPage=false;exposure.Paragraph("NSCP 2015 Section 207A.7: surface roughness is mapped in the two upwind sectors extending 45° either side of each wind-from direction (five rays at 22.5°: −45°, −22.5°, 0°, +22.5°, +45°). Exposure B needs Surface Roughness B continuously for the B fetch; Exposure D needs Surface Roughness D for the D fetch, starting at or within the transition distance of the site; Exposure C applies otherwise. The more severe sector governs.");
   var first=directions.First(d=>d.ExposureAudit!=null).ExposureAudit;exposure.Table(new[]{"Criterion","Distance m","Basis"},first.Checks.Skip(2).Take(3).Select(c=>new[]{c[0],c[1],c[2]}));
   exposure.Table(new[]{"From","Roughness mix","Continuous B m","Nearest water m","Longest water m","D rays","Exposure"},directions.Select(d=>{var a=d.ExposureAudit;return a==null?new[]{d.Name,"","","","","",d.Exposure}:new[]{d.Name,a.Mix,F(a.ShortestB),WindTin.Finite(a.NearestWater)?F(a.NearestWater):"none",F(a.LongestWater),a.SmoothRays+" / "+a.Rays,d.Exposure};}));
   foreach(var d in directions)if(d.ExposureAudit!=null)exposure.Paragraph(d.Name+": "+d.ExposureAudit.Reason);
   exposure.Note("Land cover identifies potential roughness only. Confirm obstruction heights and spacing (B), open-terrain conditions (C) and flat unobstructed water (D) on site.");
   var kzt=report.Section("Topographic factor Kzt: criteria and substitution by direction");kzt.NewPage=false;kzt.Paragraph("NSCP 2015 Section 207A.8.1: wind speed-up is applied only when all five conditions are met - (1) the feature is isolated for 100H or 3.22 km, (2) it protrudes at least twice the height of upwind features within 3.22 km, (3) the site is in the upper half of a hill or ridge or near the crest of an escarpment, (4) H/Lh ≥ 0.2, and (5) H ≥ 4.5 m for Exposure C and D or 18 m for Exposure B. Otherwise Kzt = 1.00.");
   kzt.Equation("Kzt = (1 + K1 K2 K3)²;   K1 = (K1/(H/Lh)) · min(H/Lh, 0.5);   K2 = 1 − |x| / (μ Lh);   K3 = e^(−γ z / Lh)");
   /* each direction's terrain profile right before its Kzt check (owner, 28 November 2026: "terrain profile before kzt check sa report") */
   foreach(var d in directions){kzt.Figure(Profile(d),d.Name+" wind-from terrain profile. Elevations in metres; signed distance in km, positive upwind. "+d.Status,true);if(d.TopographicChecks.Count==0)continue;kzt.Table(new[]{d.Name+" - check","Value","Basis / decision"},d.TopographicChecks.Select(c=>new[]{c[0],c[1],c[2]}));}}
  if(building!=null&&terrain!=null){var staad=report.Section("STAAD wind input data");staad.NewPage=false;var bd=WindAssessment.Calculate(terrain,building.Height,wind.V,building.Kd,building.Height);var profile=WindStaadInput.Profile(building,wind.V,building.Kd,bd);
   staad.Paragraph("Velocity pressure qz by height for each wind-from direction (kN/m²). qz is not a design surface pressure; it must be multiplied by G and Cp.");staad.Table(new[]{"From","Exposure","z m","Kz","Kzt","qz kPa"},profile.Select(r=>new[]{r.Direction,r.Exposure,F(r.Height),F(r.Kz),F(r.Kzt),F(r.Qz)}));
   var walls=WindStaadInput.WallBands(building,wind.V,bd);staad.Paragraph("Wall pressures for STAAD DEFINE WIND LOAD (INT / HEIG). Each band intensity is the windward pressure qz·G·Cp at the top of the band plus the leeward suction magnitude qh·G·|Cp|; internal pressure cancels on the two walls. Apply roof pressures separately.");
   staad.Table(new[]{"Wind from / axis","Band top z m","Windward kPa","Leeward kPa","INT (combined) kPa"},walls.Select(r=>new[]{r.Axis,F(r.Top),F(r.Windward),F(r.Leeward),F(r.Combined)}));
   staad.Equation(WindStaadInput.Commands(walls));staad.Note("Check the STAAD wind direction, exposure factors and panel definitions. Do not apply G and Cp again in STAAD, and do not combine these intensities with a separate qz-based STAAD wind definition.");}
  if(building!=null){building.Validate();if(terrain==null)throw new Exception("Load terrain before exporting building pressures.");var bd=WindAssessment.Calculate(terrain,building.Height,wind.V,building.Kd);var rows=WindBuildingLoads.Calculate(building,wind.V,bd);var geometry=report.Section("Building geometry and pressure basis");geometry.NewPage=false;geometry.Table(new[]{"Input","Value"},new[]{new[]{"Width across ridge / length along ridge",F(building.Width)+" m / "+F(building.Length)+" m"},new[]{"Eave / apex height",F(building.Eave)+" m / "+F(building.Apex)+" m"},new[]{"Roof slope / mean roof height",F(building.Angle)+"° / "+F(building.Height)+" m"},new[]{"Ridge alignment",WindBuildingLoads.RidgeName(building.Ridge)},new[]{"Building system / enclosure",building.System+" / "+building.Enclosure},new[]{"Gust factor",building.AutoG?"Calculated; rigid or flexible response based on natural frequency":"User value G = "+F(building.UserG)},new[]{"Positive internal pressure reference",building.OpeningHeight>0?F(building.OpeningHeight)+" m":"Mean roof height"}});geometry.Equation("p = q G Cp − qi (GCpi)  [kPa]\nPositive p: toward the surface. Negative p: away from the surface.");geometry.Note("The following are gross surface pressures for enclosed/partially enclosed rectangular gable/hip or flat-roof buildings (0–60°). Apply required MWFRS minimum forces, load patterns, torsion and load combinations separately. Components/cladding, open roofs, parapets and overhangs require separate calculations.");
   foreach(var axis in rows.GroupBy(r=>r.Direction)){var section=report.Section("Surface pressures · "+axis.Key);section.NewPage=false;
    section.Table(new[]{"Exposure","G","Kh at h","Kzt at h","qh kPa"},new[]{new[]{axis.First().Exposure,F(axis.First().G),F(WindBuildingLoads.Kz(axis.First().Exposure,building.Height)),F(WindBuildingLoads.TopographyAt(bd[axis.First().TerrainDirection],building.Height)),F(axis.First().Qh)}});
    section.Paragraph("Both signs of GCpi are retained. Roof Cp branches are separate load cases. GCpi is "+(building.Enclosure=="Enclosed"?"±0.18":"±0.55")+".");
    var pairs=axis.GroupBy(r=>r.Surface+"|"+r.Case.Substring(0,r.Case.LastIndexOf("; GCpi",StringComparison.Ordinal))).ToList();
    section.Table(new[]{"Surface","Case / zone","q kPa","G","Cp","qi+ kPa","qi− kPa","p+ kPa","p− kPa"},pairs.Select(pair=>{var positive=pair.First(r=>r.GCpi>0);var negative=pair.First(r=>r.GCpi<0);return new[]{positive.Surface,positive.Case.Substring(0,positive.Case.LastIndexOf("; GCpi",StringComparison.Ordinal)),F(positive.Q),F(positive.G),F(positive.Cp),F(positive.Qi),F(negative.Qi),F(positive.P),F(negative.P)};}));
    var sample=axis.First(r=>r.Surface=="Windward wall"&&r.Z>0);section.Equation("Example substitution at z = "+F(sample.Z)+" m\np = ("+F(sample.Q)+") ("+F(sample.G)+") ("+F(sample.Cp)+") − ("+F(sample.Qi)+") ("+F(sample.GCpi)+")\np = "+F(sample.P)+" kPa");
    section.Table(new[]{"Windward z m","Kz","Kzt(z)","qz kPa"},axis.Where(r=>r.Surface=="Windward wall"&&r.GCpi>0).Select(r=>new[]{F(r.Z),F(r.Kz),F(r.Kzt),F(r.Q)}));
   }
  }
  var refs=report.Section("References, interpolation and review notes");refs.Paragraph("NSCP 2015 directional procedure. Wind contours and calculation basis: supplied RCB Wind v.3.3.xlsm. Wall Cp uses windward +0.8, side −0.7 and the leeward L/B interpolation. Roof coefficients use Figure 207B.4-1 interpolation with the high h/L row applying at h/L ≥ 1.");refs.Paragraph("Terrain: AWS Terrarium elevation tiles (~30–40 m sampling); ESA WorldCover 2021 v200, 10 m source data, DOI 10.5281/zenodo.7254221, CC BY 4.0. The display grid is sampled more coarsely; it is not a surveyed exposure boundary.");refs.Paragraph("Site basemap: OpenStreetMap contributors or Esri World Imagery / Maxar / Earthstar Geographics when shown. Basemap imagery is separate from the elevation and roughness datasets.");refs.Note(wind.Coastal?"Site lies outside the TIN hull. Nearest-contour continuation was used; verify the applicable wind contour.":"Inside TIN hull. Linear barycentric interpolation of digitized contour nodes was used; this is not an exact authoritative georeferenced wind dataset.");
  return report;
 }
 static string N(double value){return value.ToString("0.##",CultureInfo.InvariantCulture);}
 static string Color(int cover){string c=WindAssessment.Roughness(cover);return c=="B"?"#26874e":c=="C"?"#bf9015":c=="D"?"#2576bd":"#909ba8";}
 public static string Profile(WindDirection d){var points=d.Profile.Where(p=>WindTin.Finite(p.Z)).ToList();if(points.Count<2)return "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 800 220'><text x='30' y='50'>Terrain profile unresolved</text></svg>";double min=points.Min(p=>p.Z),max=points.Max(p=>p.Z);double first=points.First().D,last=points.Last().D;double ve=TerrainProfileScale.AutoExaggeration(first,last,min,max,700,106);var scale=TerrainProfileScale.Create(first,last,min,max,62,52,700,106,ve);Func<double,double> x=v=>scale.X(v),y=v=>scale.Y(v);var b=new StringBuilder("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 800 220' font-family='Arial' font-size='14'><rect width='800' height='220' fill='white'/>");b.Append("<text x='20' y='24' font-size='15' font-weight='bold' fill='#243d56'>").Append(EngineeringReport.Escape(d.Name+" · Exposure "+d.Exposure+" · "+d.Shape)).Append("</text>");
  for(int i=0;i<5;i++){double elevation=scale.TickZ(i/4.0);b.Append("<path stroke='#e3e9ef' d='M62 ").Append(N(y(elevation))).Append("H762'/><text fill='#64768a' x='6' y='").Append(N(y(elevation)+4)).Append("'>").Append(N(elevation)).Append(" m</text>");}
  for(int i=1;i<points.Count;i++){if(points[i].D-points[i-1].D>150)continue;string a=N(x(points[i-1].D)),c=N(x(points[i].D)),az=N(y(points[i-1].Z)),cz=N(y(points[i].Z)),color=Color(points[i-1].Cover);b.Append("<path fill='").Append(color).Append("' fill-opacity='.08' d='M").Append(a).Append(" 158V").Append(az).Append("L").Append(c).Append(' ').Append(cz).Append("V158Z'/><path fill='none' stroke='").Append(color).Append("' stroke-width='2.5' d='M").Append(a).Append(' ').Append(az).Append('L').Append(c).Append(' ').Append(cz).Append("'/>");}
  b.Append("<path stroke='#3a4d60' stroke-dasharray='4 4' d='M").Append(N(x(0))).Append(" 46V164'/><text x='").Append(N(x(0)+6)).Append("' y='46' fill='#314a63'>PROJECT SITE</text>");for(int i=0;i<5;i++){double distance=first+(last-first)*i/4;b.Append("<text x='").Append(N(x(distance)-15)).Append("' y='181' fill='#61758b'>").Append(N(distance/1000)).Append(" km</text>");}return b.Append("<text x='62' y='207' fill='#64768a'>B green · C gold · D blue · unknown gray   |   +distance upwind   |   one scale for distance and elevation, VE = ").Append(ve.ToString("0",CultureInfo.InvariantCulture)).Append("×</text></svg>").ToString();
 }
 static string RoughnessPlan(WindTerrain terrain,double height){double radius=terrain.Radius;Func<double,double,double[]> xy=(lat,lon)=>{double dy=(lat-terrain.Lat)*111195,dx=(lon-terrain.Lon)*111195*Math.Cos(terrain.Lat*Math.PI/180);return new[]{400+dx/radius*260,290-dy/radius*260};};var b=new StringBuilder("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 800 610' font-family='Arial' font-size='14'><rect width='800' height='610' fill='#f5f8fb'/>");
  var grid=terrain.CoverGrid;if(grid!=null)for(int row=0;row<grid.Size;row++)for(int col=0;col<grid.Size;col++){var a=xy(grid.North-row*(grid.North-grid.South)/grid.Size,grid.West+col*(grid.East-grid.West)/grid.Size);var c=xy(grid.North-(row+1)*(grid.North-grid.South)/grid.Size,grid.West+(col+1)*(grid.East-grid.West)/grid.Size);b.Append("<rect x='").Append(N(a[0])).Append("' y='").Append(N(a[1])).Append("' width='").Append(N(c[0]-a[0]+.2)).Append("' height='").Append(N(c[1]-a[1]+.2)).Append("' fill='").Append(Color(grid.Codes[row*grid.Size+col])).Append("' fill-opacity='.18'/>");}
  foreach(double fraction in new[]{.5,1.0})b.Append("<circle cx='400' cy='290' r='").Append(N(260*fraction)).Append("' fill='none' stroke='#bdcbd8'/><text x='405' y='").Append(N(290-260*fraction+15)).Append("' fill='#536d85'>").Append(N(radius*fraction/1000)).Append(" km</text>");
  for(int i=0;i<8;i++){var ray=terrain.Rays[i*3+1];var sector=WindAssessment.Destination(terrain.Lat,terrain.Lon,terrain.Offset+i*45-22.5,radius);var boundary=xy(sector[0],sector[1]);b.Append("<path stroke='#95a8bc' stroke-dasharray='4 4' d='M400 290L").Append(N(boundary[0])).Append(' ').Append(N(boundary[1])).Append("'/>");for(int j=1;j<ray.Count;j++){var a=xy(ray[j-1].Lat,ray[j-1].Lon);var c=xy(ray[j].Lat,ray[j].Lon);b.Append("<path stroke='").Append(Color(ray[j-1].Cover)).Append("' stroke-width='4' d='M").Append(N(a[0])).Append(' ').Append(N(a[1])).Append('L').Append(N(c[0])).Append(' ').Append(N(c[1])).Append("'/>");}var end=WindAssessment.Destination(terrain.Lat,terrain.Lon,i*45,radius*1.08);var p=xy(end[0],end[1]);b.Append("<text text-anchor='middle' fill='#284663' font-weight='bold' x='").Append(N(p[0])).Append("' y='").Append(N(p[1]+4)).Append("'>").Append(WindAssessment.Directions[i]).Append(" / ").Append(WindAssessment.Exposure(terrain,i,height)).Append("</text>");}
  return b.Append("<circle cx='400' cy='290' r='7' fill='#203d59' stroke='white' stroke-width='2'/><text x='410' y='282' fill='#203d59' font-weight='bold'>PROJECT SITE</text><text x='22' y='590' fill='#64798f'>Surface roughness: B green · C gold · D blue · unknown gray</text></svg>").ToString();
 }
}
